// HDMI_CEC_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module HDMI_CEC_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_enable,
  input logic [3:0] c_la,
  input logic  c_promisc,
  input logic [15:0] c_tick_div,
  input logic [9:0] c_sft,
  input logic [31:0] c_rx_base,
  input logic [7:0] c_rx_slots,
  input logic [7:0] c_rx_rd,
  input logic [31:0] c_tx_addr,
  input logic  c_tx_start,
  input logic [7:0] c_rx_wr,
  input logic [3:0] c_tx_status,
  input logic  c_tx_busy,
  input logic [15:0] c_rx_cnt,
  input logic [15:0] c_rx_err_cnt,
  input logic [15:0] c_rx_ovf_cnt,
  input logic  c_rx,
  input logic  c_rx_err,
  input logic  c_tx_done,
  input logic  c_err_irq
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 15;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:14];          // model of every stored word
  logic [3:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_rx) m_set[0] = 1'b1;
    if (c_rx_err) m_set[1] = 1'b1;
    if (c_tx_done) m_set[2] = 1'b1;
    if (c_err_irq) m_set[3] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h3F;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h3FFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 10) ? PWDATA & m_be & 32'h1 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h7C060100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return 0;
      11: return (32'(c_rx_wr) << 0);
      12: return (32'(c_tx_status) << 0) | (32'(c_tx_busy) << 4);
      13: return (32'(c_rx_cnt) << 0) | (32'(c_rx_err_cnt) << 16);
      14: return (32'(c_rx_ovf_cnt) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][3:0] & m_w[2][3:0]))
  `SVA_INV(a_core_enable, c_enable == m_w[5][0:0])
  `SVA_INV(a_core_la, c_la == m_w[5][4:1])
  `SVA_INV(a_core_promisc, c_promisc == m_w[5][5:5])
  `SVA_INV(a_core_tick_div, c_tick_div == m_w[6][15:0])
  `SVA_INV(a_core_sft, c_sft == m_w[6][25:16])
  `SVA_INV(a_core_rx_base, c_rx_base == m_w[7][31:0])
  `SVA_INV(a_core_rx_slots, c_rx_slots == m_w[8][7:0])
  `SVA_INV(a_core_rx_rd, c_rx_rd == m_w[8][15:8])
  `SVA_INV(a_core_tx_addr, c_tx_addr == m_w[9][31:0])
  `SVA_INV(a_core_tx_start, c_tx_start == m_pulse_CMD[0])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_enable == 1'h0 && c_la == 4'h0 && c_promisc == 1'h0 && c_tick_div == 16'h0 && c_sft == 10'h0 && c_rx_base == 32'h0 && c_rx_slots == 8'h0 && c_rx_rd == 8'h0 && c_tx_addr == 32'h0 && c_tx_start == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_TIMING, m_rd && m_map && m_idx == 6)
  `FC(wr_TIMING, m_wr && m_map && m_idx == 6)
  `FC(rd_RX_BASE, m_rd && m_map && m_idx == 7)
  `FC(wr_RX_BASE, m_wr && m_map && m_idx == 7)
  `FC(rd_RX_RING, m_rd && m_map && m_idx == 8)
  `FC(wr_RX_RING, m_wr && m_map && m_idx == 8)
  `FC(rd_TX_ADDR, m_rd && m_map && m_idx == 9)
  `FC(wr_TX_ADDR, m_wr && m_map && m_idx == 9)
  `FC(rd_CMD, m_rd && m_map && m_idx == 10)
  `FC(wr_CMD, m_wr && m_map && m_idx == 10)
  `FC(rd_RX_WR, m_rd && m_map && m_idx == 11)
  `FC(wr_RX_WR, m_wr && m_map && m_idx == 11)
  `FC(rd_TX, m_rd && m_map && m_idx == 12)
  `FC(wr_TX, m_wr && m_map && m_idx == 12)
  `FC(rd_RX_CNT, m_rd && m_map && m_idx == 13)
  `FC(wr_RX_CNT, m_wr && m_map && m_idx == 13)
  `FC(rd_RX_OVF, m_rd && m_map && m_idx == 14)
  `FC(wr_RX_OVF, m_wr && m_map && m_idx == 14)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_RX_set, m_set[0])
  `FC(irq_RX_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_RX_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_RX_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_RX_ERR_set, m_set[1])
  `FC(irq_RX_ERR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_RX_ERR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_RX_ERR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_TX_DONE_set, m_set[2])
  `FC(irq_TX_DONE_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_TX_DONE_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_TX_DONE_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_ERR_set, m_set[3])
  `FC(irq_ERR_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_ERR_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_ERR_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(cmd_tx_start, m_pulse_CMD[0])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind HDMI_CEC_apb HDMI_CEC_apb_sva u_apb_sva (.*);
